+const pptxgen = require("pptxgenjs");
+const { addTopBar, addPageBadge, addSource } = require("./utils");
+
+const slideConfig = {
+  type: "content",
+  index: 4,
+  title: "Renewable Electricity Generation Is Growing Rapidly, Led by Wind and Solar"
+};
+
+const generationTWh = [
+  { tech: "Hydropower", value: 4500, colorKey: "primary" },
+  { tech: "Wind", value: 2400, colorKey: "secondary" },
+  { tech: "Solar", value: 2000, colorKey: "light" },
+  { tech: "Other", value: 700, colorKey: "accent" }
+];
+
+function createSlide(pres, theme) {
+  const slide = pres.addSlide();
+  slide.background = { color: theme.bg };
+
+  addTopBar(slide, theme, slideConfig.title, "Approx. global renewable electricity generation by technology (2024). ");
+
+  // Chart area
+  slide.addShape(pptxgen.ShapeType.roundRect, {
+    x: 0.7,
+    y: 1.35,
+    w: 8.2,
+    h: 4.2,
+    fill: { color: "ffffff" },
+    line: { color: theme.secondary, transparency: 65 },
+    radius: 0.2
+  });
+
+  const maxVal = Math.max(...generationTWh.map((d) => d.value));
+  const chartX = 1.15;
+  const chartY = 1.95;
+  const chartW = 7.3;
+  const barH = 0.55;
+  const gap = 0.45;
+
+  generationTWh.forEach((d, i) => {
+    const y = chartY + i * (barH + gap);
+    const w = (d.value / maxVal) * chartW;
+    slide.addText(d.tech, {
+      x: chartX,
+      y: y - 0.25,
+      w: 2.2,
+      h: 0.3,
+      fontFace: "Calibri",
+      fontSize: 12,
+      color: theme.primary
+    });
+    slide.addShape(pptxgen.ShapeType.roundRect, {
+      x: chartX,
+      y,
+      w,
+      h: barH,
+      fill: { color: theme[d.colorKey] },
+      line: { color: theme[d.colorKey] },
+      radius: 0.12
+    });
+    slide.addText(`~${d.value.toLocaleString()} TWh`, {
+      x: chartX + w + 0.1,
+      y: y + 0.12,
+      w: 1.6,
+      h: 0.25,
+      fontFace: "Calibri",
+      fontSize: 12,
+      color: theme.primary
+    });
+  });
+
+  // Right insights panel
+  slide.addShape(pptxgen.ShapeType.roundRect, {
+    x: 9.2,
+    y: 1.35,
+    w: 3.75,
+    h: 4.2,
+    fill: { color: theme.secondary, transparency: 10 },
+    line: { color: theme.secondary, transparency: 10 },
+    radius: 0.2
+  });
+
+  slide.addText("What to notice", {
+    x: 9.45,
+    y: 1.55,
+    w: 3.3,
+    h: 0.35,
+    fontFace: "Cambria",
+    fontSize: 18,
+    bold: true,
+    color: theme.primary
+  });
+  slide.addText(
+    "• Hydropower remains the largest source (~4,500 TWh).\n• Wind (~2,400 TWh) + solar (~2,000 TWh) combined now nearly match hydro output.\n• Wind and solar have accelerated since ~2010 (cost declines + policy support).",
+    {
+      x: 9.45,
+      y: 2.0,
+      w: 3.25,
+      h: 3.2,
+      fontFace: "Calibri",
+      fontSize: 13,
+      color: theme.primary,
+      valign: "top"
+    }
+  );
+
+  addSource(slide, theme, "Source: Our World in Data – Renewable Energy (approx. 2024 generation, TWh). ");
+  addPageBadge(slide, theme, 4, 9);
+  return slide;
+}
+
+module.exports = { createSlide, slideConfig };
+
*** End Patch
PATCH

