const path = require("path");
const pptxgen = require("pptxgenjs");
const { addTopBar, addPageBadge, addSource, addFigure } = require("./utils");

const slideConfig = {
  type: "content",
  index: 5,
  title: "Almost One-Third of Global Electricity Now Comes from Renewables"
};

const tableRows = [
  ["Norway", "~98%"],
  ["Brazil", "~85%"],
  ["Canada", "~65%"],
  ["China", "~35%"],
  ["India", "~25%"],
  ["Saudi Arabia", "<2%"]
];

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.bg };

  addTopBar(slide, theme, slideConfig.title, "Renewable electricity share by country (2025). ");

  // Map on left
  const figPath = path.join(__dirname, "imgs", "figure_1.jpg");
  addFigure(slide, figPath, { x: 0.7, y: 1.25, w: 8.1, h: 4.55 }, "contain");
  slide.addText("Share of electricity from renewables by country (2025)", {
    x: 0.7,
    y: 5.05,
    w: 8.1,
    h: 0.3,
    fontFace: "Calibri",
    fontSize: 11,
    color: theme.secondary
  });

  // Right: table + narrative
  slide.addShape(pptxgen.ShapeType.roundRect, {
    x: 9.0,
    y: 1.25,
    w: 4.05,
    h: 4.55,
    fill: { color: "ffffff" },
    line: { color: theme.secondary, transparency: 65 },
    radius: 0.2
  });

  slide.addText("Selected countries/regions", {
    x: 9.25,
    y: 1.45,
    w: 3.55,
    h: 0.35,
    fontFace: "Cambria",
    fontSize: 16,
    bold: true,
    color: theme.primary
  });

  // Table header
  slide.addShape(pptxgen.ShapeType.roundRect, {
    x: 9.25,
    y: 1.85,
    w: 3.55,
    h: 0.35,
    fill: { color: theme.primary },
    line: { color: theme.primary },
    radius: 0.12
  });
  slide.addText("Country", {
    x: 9.35,
    y: 1.92,
    w: 2.2,
    h: 0.22,
    fontFace: "Calibri",
    fontSize: 12,
    color: theme.bg
  });
  slide.addText("Renewable share", {
    x: 11.35,
    y: 1.92,
    w: 1.4,
    h: 0.22,
    fontFace: "Calibri",
    fontSize: 12,
    color: theme.bg,
    align: "right"
  });

  const startY = 2.25;
  const rowH = 0.42;
  tableRows.forEach((r, i) => {
    const y = startY + i * rowH;
    slide.addShape(pptxgen.ShapeType.rect, {
      x: 9.25,
      y,
      w: 3.55,
      h: rowH,
      fill: { color: i % 2 === 0 ? theme.bg : "ffffff" },
      line: { color: theme.secondary, transparency: 85 }
    });
    slide.addText(r[0], {
      x: 9.35,
      y: y + 0.1,
      w: 2.3,
      h: 0.25,
      fontFace: "Calibri",
      fontSize: 12,
      color: theme.primary
    });
    slide.addText(r[1], {
      x: 11.55,
      y: y + 0.1,
      w: 1.25,
      h: 0.25,
      fontFace: "Calibri",
      fontSize: 12,
      color: theme.primary,
      align: "right"
    });
  });

  slide.addShape(pptxgen.ShapeType.roundRect, {
    x: 9.25,
    y: 4.95,
    w: 3.55,
    h: 0.7,
    fill: { color: theme.light, transparency: 25 },
    line: { color: theme.light, transparency: 25 },
    radius: 0.18
  });
  slide.addText(
    "Pattern: Latin America and the Nordics often exceed 60–90%+, while parts of the Middle East remain below 10%.",
    {
      x: 9.35,
      y: 5.02,
      w: 3.35,
      h: 0.6,
      fontFace: "Calibri",
      fontSize: 11,
      color: theme.primary,
      valign: "top"
    }
  );

  addSource(slide, theme, "Source: Our World in Data – Renewable Energy (approx. 2025 shares). ");
  addPageBadge(slide, theme, 5, 9);
  return slide;
}

module.exports = { createSlide, slideConfig };

