const pptxgen = require("pptxgenjs");
const { addPageBadge, addSource } = require("./utils");

const slideConfig = {
  type: "summary",
  index: 9,
  title: "Key Takeaways: Renewables Are Growing Fast but the Transition Must Accelerate"
};

function createSlide(pres, theme) {
  const slide = pres.addSlide();
  slide.background = { color: theme.primary };

  // Header
  slide.addText(slideConfig.title, {
    x: 0.75,
    y: 0.65,
    w: 11.9,
    h: 0.9,
    fontFace: "Cambria",
    fontSize: 34,
    bold: true,
    color: theme.bg
  });

  // Left: takeaways
  slide.addShape(pptxgen.ShapeType.roundRect, {
    x: 0.75,
    y: 1.7,
    w: 7.3,
    h: 3.75,
    fill: { color: "ffffff", transparency: 6 },
    line: { color: "ffffff", transparency: 80 },
    radius: 0.25
  });

  const takeaways = [
    "~14% of global primary energy and ~30% of global electricity are renewable.",
    "Hydropower is still dominant (roughly half of renewable electricity).",
    "Wind (~2,400 TWh) and solar (~2,000 TWh) are scaling rapidly and together nearly match hydro output.",
    "Regional disparities remain: Scandinavia/Latin America lead; parts of the Middle East and Sub-Saharan Africa lag.",
    "Transport and heating lag behind electricity, keeping overall primary-energy progress slower."
  ];

  slide.addText("What this means for strategy", {
    x: 1.1,
    y: 1.95,
    w: 6.8,
    h: 0.35,
    fontFace: "Cambria",
    fontSize: 18,
    bold: true,
    color: theme.primary
  });
  slide.addText(
    takeaways.map((t) => `• ${t}`).join("\n"),
    {
      x: 1.1,
      y: 2.35,
      w: 6.8,
      h: 3.0,
      fontFace: "Calibri",
      fontSize: 14,
      color: theme.primary,
      valign: "top"
    }
  );

  // Right: call to action
  slide.addShape(pptxgen.ShapeType.roundRect, {
    x: 8.35,
    y: 1.7,
    w: 4.25,
    h: 3.75,
    fill: { color: theme.secondary },
    line: { color: theme.secondary },
    radius: 0.25
  });

  slide.addText("Accelerate the transition", {
    x: 8.65,
    y: 1.95,
    w: 3.7,
    h: 0.5,
    fontFace: "Cambria",
    fontSize: 20,
    bold: true,
    color: theme.bg
  });

  slide.addText(
    "Policy and investment can close gaps by:\n\n• Scaling wind + solar deployment\n• Modernizing grids and enabling flexibility\n• Expanding clean electrification beyond power (transport + heat)",
    {
      x: 8.65,
      y: 2.55,
      w: 3.7,
      h: 2.6,
      fontFace: "Calibri",
      fontSize: 13,
      color: theme.bg,
      valign: "top"
    }
  );

  // Footer source
  slide.addText("Source: Our World in Data – Renewable Energy.", {
    x: 0.75,
    y: 5.25,
    w: 10.0,
    h: 0.3,
    fontFace: "Calibri",
    fontSize: 10,
    color: theme.bg
  });

  // Page badge (with inverted colors)
  slide.addShape(pptxgen.ShapeType.roundRect, {
    x: 12.35,
    y: 5.15,
    w: 0.75,
    h: 0.35,
    fill: { color: theme.bg },
    line: { color: theme.bg },
    radius: 0.12
  });
  slide.addText("9/9", {
    x: 12.35,
    y: 5.22,
    w: 0.75,
    h: 0.2,
    fontFace: "Calibri",
    fontSize: 11,
    color: theme.primary,
    align: "center"
  });

  return slide;
}

module.exports = { createSlide, slideConfig };

